import re
import shlex
import subprocess
import time

import requests

from hran_pacman.bases.fdsw_base import FDSWDownloader
from hran_pacman.exceptions import SVNContentError, SVNContentNotFound

SEM_INSTALLER_NAME = ".*BTSSiteEM.*exe"
SVN_COMMON_OPT = (
    "--username ca_wcdma_cbr_man "
    + "--password wcmp4ss "
    + "--no-auth-cache "
    + "--non-interactive "
    + "--trust-server-cert"
)
MAX_RETRIES = 5
SLEEP_TIME = 10


class FDSWPackageDownloader(FDSWDownloader):
    technology = "FDSW"

    @property
    def downloadable_name(self):
        return "{}_release_BTSSM_downloadable.zip".format(self.baseline)

    def get_site_manager(self):
        sem_url = self.get_sm_url()
        FDSWSemDownloader(sem_url).download_sem_from_svn()


class FDSWSemDownloader(object):
    def __init__(self, svn_url, rev=0):
        self.svn_url = svn_url
        self.rev = rev

    def download_sem_from_svn(self):
        self._export_sem()

    def _list_svn(self):
        svn_command = shlex.split("svn ls -R {0} {1}".format(SVN_COMMON_OPT, self.svn_url))
        return self.execute_command(svn_command).splitlines()

    def _find_setup_url(self):
        sem_files = self._list_svn()
        sem_installer_regex = re.compile(SEM_INSTALLER_NAME)
        sem_setup_url = ""
        for sem_file in sem_files:
            if sem_installer_regex.match(sem_file):
                sem_setup_url = self.svn_url + "/" + sem_file
                break
        if not sem_setup_url:
            raise SVNContentNotFound("Error occurred during searching sem installer file. File not found")
        return sem_setup_url

    def _export_sem(self):
        try:
            url = self._find_setup_url()
            svn_command = shlex.split("svn export --force {0} {1}".format(SVN_COMMON_OPT, url))
            self.execute_command(svn_command)
        except (SVNContentError, SVNContentNotFound):
            self._download_via_request()

    def _download_via_request(self):
        try:
            with open(self.svn_url.split("/")[-1], "wb") as target:
                response = requests.get(self.svn_url, allow_redirects=True, stream=True)
                for chunk in response.iter_content(chunk_size=4096):
                    target.write(chunk)
        except Exception:
            raise SVNContentNotFound("Error occurred during searching sem installer file. File not found")

    @staticmethod
    def execute_command(command):
        out = None
        for _ in range(MAX_RETRIES):
            try:
                out = subprocess.check_output(command)
                break
            except subprocess.CalledProcessError:
                time.sleep(SLEEP_TIME)
        if not out:
            raise SVNContentError("Error occurred during executing command:\n{0}".format(" ".join(command)))
        return out
